{"content":"/**
 * 统一素材上传工具
 * 处理图片和视频上传，获取 asset_id
 */
import { getApiBase } from "@/lib/api";

export interface UploadResult {
  success: boolean;
  assetId?: string;
  url?: string;
  error?: string;
}

const ASSET_GROUP_URL = "/videos/doubao-seedance-2-0/private-avatar/groups";
const ASSET_UPLOAD_URL = "/videos/doubao-seedance-2-0/private-avatar/assets";

/**
 * 直接上传文件到 toapis.com asset 系统
 * 流程：创建group → 上传文件 → 轮询等待active → 返回assetId
 */
export async function uploadToAsset(
  file: File,
  apiUrl: string,
  apiKey: string,
  onProgress?: (progress: number) => void
): Promise<UploadResult> {
  try {
    const base = apiUrl.replace(/\/+$/, "");
    const headers = { Authorization: `Bearer ${apiKey}` };

    // 1. 创建 Group
    onProgress?.(5);
    const groupResp = await fetch(`${base}${ASSET_GROUP_URL}`, {
      method: "POST",
      headers: { ...headers, "Content-Type": "application/json" },
      body: JSON.stringify({ name: "antoken-upload" }),
    });
    if (!groupResp.ok) {
      const err = await groupResp.text();
      return { success: false, error: `创建Group失败: ${err}` };
    }
    const groupData = await groupResp.json();
    const groupId = groupData?.data?.group_id;
    if (!groupId) return { success: false, error: "未返回group_id" };

    // 2. 上传文件（multipart）
    onProgress?.(20);
    const assetType = file.type.startsWith("video/") ? "video" : "image";
    const formData = new FormData();
    formData.append("file", file);
    formData.append("group_id", groupId);
    formData.append("asset_type", assetType);

    const uploadResp = await fetch(`${base}${ASSET_UPLOAD_URL}`, {
      method: "POST",
      headers,
      body: formData,
    });
    if (!uploadResp.ok) {
      const err = await uploadResp.text();
      return { success: false, error: `上传失败: ${err}` };
    }
    const uploadData = await uploadResp.json();
    const assetId = uploadData?.data?.asset_id;
    if (!assetId) return { success: false, error: "未返回asset_id" };

    // 3. 轮询等待 active
    onProgress?.(50);
    for (let i = 0; i < 30; i++) {
      await new Promise((r) => setTimeout(r, 2000));
      const statusResp = await fetch(`${base}${ASSET_UPLOAD_URL}/${assetId}`, { headers });
      if (statusResp.ok) {
        const statusData = await statusResp.json();
        const status = statusData?.data?.status;
        onProgress?.(50 + Math.min(i * 3, 45));
        if (status === "active") {
          onProgress?.(100);
          return { success: true, assetId };
        }
        if (status === "failed") return { success: false, error: "Asset处理失败" };
      }
    }
    return { success: false, error: "Asset激活超时" };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : "上传出错" };
  }
}

/**
 * 上传文件到后端 /api/upload（用于画布拖拽等需要后端URL的场景）
 */
export async function uploadAsset(
  file: File,
  apiKey?: string,
  onProgress?: (progress: number) => void
): Promise<UploadResult> {
  try {
    const formData = new FormData();
    formData.append("file", file);

    const headers: Record<string, string> = {};
    if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;

    onProgress?.(10);
    const response = await fetch(`${getApiBase()}/api/upload`, {
      method: "POST",
      headers,
      body: formData,
    });
    onProgress?.(90);

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "上传失败" }));
      return { success: false, error: error.detail || "上传失败" };
    }

    const data = await response.json();
    onProgress?.(100);
    return {
      success: true,
      assetId: data.asset_id || data.assetId,
      url: data.url || data.asset_url || (data.path ? `${getApiBase()}${data.path}` : undefined),
    };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : "上传出错" };
  }
}

/**
 * 从 URL 获取文件并上传
 */
export async function uploadFromUrl(
  url: string,
  apiKey?: string
): Promise<UploadResult> {
  try {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;

    const response = await fetch(`${getApiBase()}/api/upload/from-url`, {
      method: "POST",
      headers,
      body: JSON.stringify({ url }),
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "上传失败" }));
      return { success: false, error: error.detail || "上传失败" };
    }

    const data = await response.json();
    return {
      success: true,
      assetId: data.asset_id || data.assetId,
      url: data.url || data.asset_url || (data.path ? `${getApiBase()}${data.path}` : undefined),
    };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : "上传出错" };
  }
}

/**
 * 获取文件类型
 */
export function getAssetType(file: File): "IMAGE" | "VIDEO" | "TEXT" {
  if (file.type.startsWith("image/")) return "IMAGE";
  if (file.type.startsWith("video/")) return "VIDEO";
  return "TEXT";
}

/**
 * 检测 URL 类型
 */
export function detectUrlType(url: string): "IMAGE" | "VIDEO" | "TEXT" {
  const ext = url.split(".").pop()?.toLowerCase() || "";
  const imageExts = ["jpg", "jpeg", "png", "gif", "webp", "bmp", "svg"];
  const videoExts = ["mp4", "webm", "mov", "avi", "mkv", "flv"];
  if (imageExts.includes(ext)) return "IMAGE";
  if (videoExts.includes(ext)) return "VIDEO";
  return "TEXT";
}

/**
 * 验证文件类型
 */
export function validateFile(file: File, allowedTypes?: string[]): boolean {
  const defaultAllowed = ["image/jpeg", "image/png", "image/gif", "image/webp", "video/mp4", "video/webm", "video/quicktime"];
  const allowed = allowedTypes || defaultAllowed;
  return allowed.includes(file.type);
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}
