{"content":"/**
 * 统一素材上传工具
 * 处理图片和视频上传
 */
import { getApiBase } from "@/lib/api";

export interface UploadResult {
  success: boolean;
  assetId?: string;
  url?: string;
  error?: string;
}

/**
 * 上传文件到后端 /api/upload
 */
export async function uploadAsset(
  file: File,
  apiKey?: string,
  onProgress?: (progress: number) => void
): Promise<UploadResult> {
  try {
    const formData = new FormData();
    formData.append("file", file);

    const headers: Record<string, string> = {};
    if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;

    onProgress?.(10);
    const response = await fetch(`${getApiBase()}/api/upload`, {
      method: "POST",
      headers,
      body: formData,
    });
    onProgress?.(90);

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "上传失败" }));
      return { success: false, error: error.detail || "上传失败" };
    }

    const data = await response.json();
    onProgress?.(100);
    return {
      success: true,
      assetId: data.asset_id || data.assetId,
      url: data.url || data.asset_url || (data.path ? `${getApiBase()}${data.path}` : undefined),
    };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : "上传出错" };
  }
}

/**
 * 从 URL 获取文件并上传
 */
export async function uploadFromUrl(
  url: string,
  apiKey?: string
): Promise<UploadResult> {
  try {
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (apiKey) headers["Authorization"] = `Bearer ${apiKey}`;

    const response = await fetch(`${getApiBase()}/api/upload/from-url`, {
      method: "POST",
      headers,
      body: JSON.stringify({ url }),
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ detail: "上传失败" }));
      return { success: false, error: error.detail || "上传失败" };
    }

    const data = await response.json();
    return {
      success: true,
      assetId: data.asset_id || data.assetId,
      url: data.url || data.asset_url || (data.path ? `${getApiBase()}${data.path}` : undefined),
    };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : "上传出错" };
  }
}

/**
 * 获取文件类型
 */
export function getAssetType(file: File): "IMAGE" | "VIDEO" | "TEXT" {
  if (file.type.startsWith("image/")) return "IMAGE";
  if (file.type.startsWith("video/")) return "VIDEO";
  return "TEXT";
}

/**
 * 检测 URL 类型
 */
export function detectUrlType(url: string): "IMAGE" | "VIDEO" | "TEXT" {
  const ext = url.split(".").pop()?.toLowerCase() || "";
  const imageExts = ["jpg", "jpeg", "png", "gif", "webp", "bmp", "svg"];
  const videoExts = ["mp4", "webm", "mov", "avi", "mkv", "flv"];
  if (imageExts.includes(ext)) return "IMAGE";
  if (videoExts.includes(ext)) return "VIDEO";
  return "TEXT";
}

/**
 * 验证文件类型
 */
export function validateFile(file: File, allowedTypes?: string[]): boolean {
  const defaultAllowed = ["image/jpeg", "image/png", "image/gif", "image/webp", "video/mp4", "video/webm", "video/quicktime"];
  const allowed = allowedTypes || defaultAllowed;
  return allowed.includes(file.type);
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}
