      const resp = await fetch(`${getApiBase()}/api/upload`, {
        method: "POST",
        body: formData,
      });

      if (!resp.ok) {
        console.error("上传失败:", resp.status);
        return null;
      }

      const data = await resp.json();
      return {
        localUrl: `${getApiBase()}${data.path}`,
