            assetUrl: data.public_url,
            config: { ...(nodes.find(n => n.id === nodeId)?.data as any)?.config, assetUrl: data.public_url },
          });
          return;
        }
      } catch {}
    }
  }, [updateNodeData, nodes]);","old_string":"  // 上传文件到后端
